body.script:
//
<![CDATA[
function togAcc8(bid,aid){var b=document.getElementById(bid);var a=document.getElementById(aid);if(b)b.classList.toggle('open');if(a)a.classList.toggle('open')}
function togDef8(pre,val){['sh','spc','new'].forEach(function(k){var el=document.getElementById(pre+'_'+k+'_sec');if(el)el.classList.add('hidden')});var show=document.getElementById(pre+'_'+val+'_sec');if(show)show.classList.remove('hidden')}
function togRes8(pre,val){var y=document.getElementById(pre+'_res_y');var n=document.getElementById(pre+'_res_n');if(val==='yes'){if(y)y.classList.remove('hidden');if(n)n.classList.add('hidden')}else{if(y)y.classList.add('hidden');if(n)n.classList.remove('hidden')}}
function togShow8(id,radio,sv){var el=document.getElementById(id);if(!el)return;radio.value===sv?el.classList.remove('hidden'):el.classList.add('hidden')}
function showFC8(cid,sel){var b=document.getElementById(cid);if(b)sel.value?b.classList.remove('hidden'):b.classList.add('hidden')}
function clearFC8(sid,cid){var s=document.getElementById(sid);if(s)s.value='';var b=document.getElementById(cid);if(b)b.classList.add('hidden')}
function togFlag8(mid){var m=document.getElementById(mid);if(m)m.classList.toggle('hidden')}
function setFlag8(bid,mid,flag,code){var b=document.getElementById(bid);if(b)b.innerHTML=flag+' '+code+' &#9660;';var m=document.getElementById(mid);if(m)m.classList.add('hidden')}
function updCnt8(el,id){var s=document.getElementById(id);if(s)s.textContent=el.value.length+' / 100'}
function saveP8(accId){var b=document.querySelector('#'+accId+' .save-btn');if(b){b.textContent='&#10003; SAVED';b.style.background='#1abc9c'}}
function delP(accId){var a=document.getElementById(accId);if(a)a.remove()}
document.addEventListener('click',function(e){document.querySelectorAll('[id$="_fm"]').forEach(function(m){if(!m.classList.contains('hidden')&&m.parentElement&&!m.parentElement.contains(e.target))m.classList.add('hidden')})});
function updateDirList(count){
    count=Math.min(Math.max(parseInt(count)||1,1),10);
    var list=document.getElementById('dirList');
    var existing=list.querySelectorAll('.accordion').length;
    if(count>existing){
        for(var i=existing+1;i<=count;i++){
            var d=document.createElement('div');d.className='accordion';d.id='dir_acc_'+i;
            d.innerHTML='<div class="accordion-header" onclick="togAcc8(\'dir_body_'+i+'\',\'dir_arrow_'+i+'\')"><span>Director '+i+'</span><span class="accordion-arrow" id="dir_arrow_'+i+'">&#9660;</span></div>'+
            '<div class="accordion-body" id="dir_body_'+i+'"><div class="person-card">'+
            '<div class="delete-btn" onclick="delP(\'dir_acc_'+i+'\')">&#128465; Delete Director</div>'+
            '<div class="sub-section"><span class="question-label">Define the manager details from one of the following selections</span>'+
            '<div class="radio-group" style="flex-wrap:wrap;gap:16px">'+
            '<label class="radio-label"><input type="radio" name="dir_'+i+'_def" value="sh" onchange="togDef8(\'dir_'+i+'\',this.value)"/> Shareholder of this entity</label>'+
            '<label class="radio-label"><input type="radio" name="dir_'+i+'_def" value="spc" onchange="togDef8(\'dir_'+i+'\',this.value)"/> Current shareholder of another entity in SPC FZ</label>'+
            '<label class="radio-label"><input type="radio" name="dir_'+i+'_def" value="new" onchange="togDef8(\'dir_'+i+'\',this.value)"/> Add new</label>'+
            '</div></div>'+
            '<div class="info-link-box"><p>Please find instructional video on how to upload UID</p><a href="https://youtu.be/T536np8xm_w" target="_blank">https://youtu.be/T536np8xm_w</a></div>'+
            '<div id="dir_'+i+'_sh_sec" class="hidden sub-section"><span class="question-label">Choose existing shareholder</span><div class="sh-select-wrap"><select class="sh-dropdown" name="dir_'+i+'_sh_val"><option value="">Select Shareholder</option></select><span style="position:absolute;right:8px;top:50%;transform:translateY(-50%);font-size:12px;color:#888;pointer-events:none">&#9660;</span></div></div>'+
            '<div id="dir_'+i+'_spc_sec" class="hidden sub-section"><div style="margin-bottom:16px"><span class="question-label">Does the Director have a Nominee?</span><div class="radio-group"><label class="radio-label"><input type="radio" name="dir_'+i+'_nom_spc" value="yes"/> Yes</label><label class="radio-label"><input type="radio" name="dir_'+i+'_nom_spc" value="no" checked="checked"/> No</label></div></div><span class="question-label">Existing user?</span><input class="flat-input" type="email" name="dir_'+i+'_spc_email" placeholder="Email" style="margin-bottom:12px"/><input class="flat-input" type="text" name="dir_'+i+'_spc_pass" placeholder="Passport number / Entity registration number" style="margin-bottom:12px"/><button type="button" class="search-btn">SEARCH</button></div>'+
            '<div id="dir_'+i+'_new_sec" class="hidden"><p style="color:#aaa;font-size:13px;padding:8px 0">Full form for Director '+i+'</p></div>'+
            '</div><div class="save-row"><button type="button" class="save-btn" onclick="saveP8(\'dir_acc_'+i+'\')">SAVE</button></div></div>';
            list.appendChild(d);
        }
    } else if(count<existing){
        for(var j=existing;j>count;j--){var el=document.getElementById('dir_acc_'+j);if(el)el.remove()}
    }
}
//

//
<![CDATA[
function togAcc9(bid,aid){var b=document.getElementById(bid);var a=document.getElementById(aid);if(b)b.classList.toggle('open');if(a)a.classList.toggle('open')}
function selectUboCard(n,val){
    ['sh','spc','new'].forEach(function(k){
        var card=document.getElementById('ubo_'+n+'_card_'+k);
        if(card)card.classList.remove('selected');
        var radio=card?card.querySelector('input[type="radio"]'):null;
        if(radio)radio.checked=false;
        var sec=document.getElementById('ubo_'+n+'_'+k+'_sec');
        if(sec)sec.classList.add('hidden');
    });
    var selCard=document.getElementById('ubo_'+n+'_card_'+val);
    if(selCard){selCard.classList.add('selected');var r=selCard.querySelector('input[type="radio"]');if(r)r.checked=true;}
    var selSec=document.getElementById('ubo_'+n+'_'+val+'_sec');
    if(selSec)selSec.classList.remove('hidden');
}
function togShow9(id,radio,sv){var el=document.getElementById(id);if(!el)return;radio.value===sv?el.classList.remove('hidden'):el.classList.add('hidden')}
function showFC9(cid,sel){var b=document.getElementById(cid);if(b)sel.value?b.classList.remove('hidden'):b.classList.add('hidden')}
function clearFC9(sid,cid){var s=document.getElementById(sid);if(s)s.value='';var b=document.getElementById(cid);if(b)b.classList.add('hidden')}
function saveUbo(accId){var b=document.querySelector('#'+accId+' .save-btn');if(b){b.textContent='&#10003; SAVED';b.style.background='#1abc9c'}}
function delUbo(accId){var a=document.getElementById(accId);if(a)a.remove()}
function updateUboList(count){
    count=Math.min(Math.max(parseInt(count)||1,1),20);
    var list=document.getElementById('uboList');
    var existing=list.querySelectorAll('.accordion').length;
    if(count>existing){
        for(var i=existing+1;i<=count;i++){
            var d=document.createElement('div');d.className='accordion';d.id='ubo_acc_'+i;
            d.innerHTML='<div class="accordion-header" onclick="togAcc9(\'ubo_body_'+i+'\',\'ubo_arrow_'+i+'\')">'+
            '<span>Details for Shareholder Arjun Menon - UBO '+i+'</span>'+
            '<span class="accordion-arrow" id="ubo_arrow_'+i+'">&#9660;</span></div>'+
            '<div class="accordion-body" id="ubo_body_'+i+'">'+
            '<div class="person-card">'+
            '<div class="delete-btn" onclick="delUbo(\'ubo_acc_'+i+'\')">&#128465; Delete UBO</div>'+
            '<div class="sub-section"><span class="question-label">Define the UBO details from one of the following selections</span>'+
            '<div class="ubo-type-cards">'+
            '<div class="ubo-type-card" id="ubo_'+i+'_card_sh" onclick="selectUboCard('+i+',\'sh\')"><div class="card-icon">&#128188;</div><input type="radio" name="ubo_'+i+'_def" value="sh"/><label>Shareholder of this entity</label></div>'+
            '<div class="ubo-type-card" id="ubo_'+i+'_card_spc" onclick="selectUboCard('+i+',\'spc\')"><div class="card-icon">&#128101;</div><input type="radio" name="ubo_'+i+'_def" value="spc"/><label>Current shareholder of another entity in SPC FZ</label></div>'+
            '<div class="ubo-type-card" id="ubo_'+i+'_card_new" onclick="selectUboCard('+i+',\'new\')"><div class="card-icon">&#128100;</div><input type="radio" name="ubo_'+i+'_def" value="new"/><label>Add new</label></div>'+
            '</div></div>'+
            '<div class="info-link-box"><p>Please find instructional video on how to upload UID</p><a href="https://youtu.be/T536np8xm_w" target="_blank">https://youtu.be/T536np8xm_w</a></div>'+
            '<input class="flat-input" type="text" name="ubo_'+i+'_work_entity" placeholder="Work entity name" style="margin-bottom:12px"/>'+
            '<textarea class="flat-textarea" name="ubo_'+i+'_work_addr" rows="2" placeholder="Work entity address" style="margin-bottom:20px"></textarea>'+
            '<div id="ubo_'+i+'_sh_sec" class="hidden sub-section"><span class="question-label">Choose existing shareholder</span><div class="sh-select-wrap"><select class="sh-dropdown" name="ubo_'+i+'_sh_val"><option value="">Select Shareholder</option></select><span style="position:absolute;right:8px;top:50%;transform:translateY(-50%);font-size:12px;color:#888;pointer-events:none">&#9660;</span></div><div class="added-ubo">Added UBO:</div></div>'+
            '<div id="ubo_'+i+'_spc_sec" class="hidden sub-section"><span class="question-label">Existing user?</span><input class="flat-input" type="email" name="ubo_'+i+'_spc_email" placeholder="Email" style="margin-bottom:12px"/><input class="flat-input" type="text" name="ubo_'+i+'_spc_pass" placeholder="Passport number / Entity registration number" style="margin-bottom:12px"/><button type="button" class="search-btn">SEARCH</button></div>'+
            '<div id="ubo_'+i+'_new_sec" class="hidden"><div class="sub-section"><span class="question-label">Select the type of UBO</span><div class="radio-group"><label class="radio-label"><input type="radio" name="ubo_'+i+'_type" value="individual"/> Individual</label><label class="radio-label"><input type="radio" name="ubo_'+i+'_type" value="trust"/> Trust</label></div></div>'+
            '<div style="margin-bottom:4px"><label style="font-size:12px;color:#aaa">Date of obtaining Shares</label></div><input class="date-flat" type="date" name="ubo_'+i+'_dos" style="margin-bottom:12px"/>'+
            '<div style="margin-bottom:4px"><label style="font-size:12px;color:#aaa">Select the date when the UBO obtained ownership</label></div><input class="date-flat" type="date" name="ubo_'+i+'_dow" style="margin-bottom:16px"/>'+
            '<div style="margin-bottom:16px"><span class="question-label">Does the UBO hold voting rights?</span><div class="radio-group"><label class="radio-label"><input type="radio" name="ubo_'+i+'_vote" value="yes"/> Yes</label><label class="radio-label"><input type="radio" name="ubo_'+i+'_vote" value="no"/> No</label></div></div>'+
            '<div class="sub-section"><span class="question-label">Select the UBO stakeholder type</span><div class="radio-group"><label class="radio-label"><input type="radio" name="ubo_'+i+'_stake" value="shareholder"/> Shareholder</label><label class="radio-label"><input type="radio" name="ubo_'+i+'_stake" value="manager"/> Manager</label><label class="radio-label"><input type="radio" name="ubo_'+i+'_stake" value="director"/> Director</label><label class="radio-label"><input type="radio" name="ubo_'+i+'_stake" value="voting"/> Voting rights</label></div></div></div>'+
            '</div><div class="save-row"><button type="button" class="save-btn" onclick="saveUbo(\'ubo_acc_'+i+'\')">SAVE</button></div></div>';
            list.appendChild(d);
        }
    } else if(count<existing){
        for(var j=existing;j>count;j--){var el=document.getElementById('ubo_acc_'+j);if(el)el.remove()}
    }
}
//
